-- Runner re-cut 2026-10-17: read-only daily-bar pull for the 252 Run-U replayable tickers
-- (295 replayable rows), 2026-02-20 -> 2026-10-16. Captured ONCE; remote name /tmp/cwp_runner_recut_daily.sql.
SET default_transaction_read_only = on;
SELECT ticker||'|'||trade_date||'|'||COALESCE(open_price::text,'')||'|'||COALESCE(high_price::text,'')||'|'||COALESCE(low_price::text,'')||'|'||close||'|'||volume
FROM mi_daily_closes
WHERE ticker = ANY(ARRAY['A','AAOI','ABCL','ABVX','ACHR','ACMR','AEHR','AFRM','AGX','AKAM','ALB','AMAT','AMD','AMKR','AMLX','AMZN','ANET','AOSL','APD','APLD','ARGX','ARM','ARMK','ARWR','ASX','AU','AVAV','AXTI','BABA','BAX','BB','BBIO','BBY','BE','BLD','BNAI','BSX','BW','CART','CAT','CAVA','CGNX','CHYM','CIEN','CLF','CLSK','CMCSA','COHR','COMP','CORZ','CRCL','CRDO','CRL','CRM','CRML','CRWD','CRWV','CSCO','DASH','DDOG','DGXX','DHI','DLTR','DOCN','DT','DY','EAT','EBAY','EL','ENPH','EOSE','ESTC','EXPD','FCEL','FIG','FIX','FLEX','FLNC','FLY','FORM','FPS','FRMI','FROG','FSLY','FTAI','FTK','FTNT','FUTU','GAP','GEV','GFS','GLW','GME','GNRC','GPRE','GWW','HAS','HEI','HPE','HUT','HWM','IBM','ICLR','INSM','INTC','IONQ','IRDM','IREN','JACK','JBL','KLAC','KLAR','KTOS','LASR','LGN','LII','LITE','LRCX','LUNR','LWLG','LXU','MANE','MANH','MAS','MCHP','MDB','MKSI','MNDY','MNST','MOD','MOH','MPWR','MRCY','MRNA','MRVL','MSFT','MSTR','MTSI','MTZ','MUSA','MXL','NBIS','NBIX','NET','NOK','NOW','NTAP','NTRA','NU','NVT','NVTS','NXPI','NXT','OKLO','OKTA','OMER','ONDS','ONTO','ORKA','OUST','P','PAG','PAYC','PENG','PINS','PLTR','POET','POWI','PRAX','PTC','PURR','PWR','PYPL','QBTS','QCOM','QLYS','QUBT','RARE','RDDT','RDW','RGTI','RIOT','RKLB','RL','RMBS','ROIV','ROK','ROKU','RPD','RUN','RVMD','RXT','SANM','SE','SEDG','SEI','SFM','SGML','SHAZ','SHOP','SITM','SMCI','SMR','SMTC','SNDK','SNOW','SNX','SOFI','SOLS','SOUN','STM','STRL','STX','SYRE','TE','TEAM','TEM','TER','TEVA','THC','TSEM','TTMI','TWLO','TWST','TXN','U','UCTT','UMAC','UMC','UNH','UPST','URI','USAR','UUUU','VEEV','VG','VIAV','VICR','VIK','VSH','WAT','WCC','WDAY','WDC','WDFC','WKC','WOLF','WST','XE','ZBRA','ZETA','ZM'])
  AND trade_date BETWEEN DATE '2026-02-20' AND DATE '2026-10-16'
ORDER BY ticker, trade_date;
